//! The app: one migrator for every crate's migrations, generated by build.rs.

/// Every crate's migrations as one migrator.
#[must_use]
pub fn migrator() -> migratr::Migrator {
    include!(concat!(env!("OUT_DIR"), "/migrator.rs"))
}

#[cfg(test)]
mod tests {
    #[test]
    fn p8_p9_p10_one_history_from_build_rs() {
        let conn = rusqlite::Connection::open_in_memory().unwrap();
        let mut exec = migratr::RusqliteExecutor::new(conn);
        let applied = super::migrator().up(&mut exec).unwrap().applied;
        println!("R2 applied: {applied:?}");
    }
}
